<?php
declare(strict_types=1);require_once __DIR__.'/../includes/bootstrap.php';if($_SERVER['REQUEST_METHOD']!=='POST'){header('Location: ../installation.php');exit;}verify_csrf();$name=trim((string)($_POST['name']??''));$phone=trim((string)($_POST['phone']??''));$location=trim((string)($_POST['location']??''));$service=trim((string)($_POST['service_type']??''));$date=$_POST['preferred_date']??null;$notes=substr(trim((string)($_POST['notes']??'')),0,1000);if($name===''||!valid_phone($phone)||$location===''||$service===''){flash('error','Please enter valid contact and location details.');header('Location: ../installation.php');exit;}$connection=db();$statement=$connection->prepare('INSERT INTO customers (full_name,phone) VALUES (?,?) ON DUPLICATE KEY UPDATE full_name=VALUES(full_name)');$statement->bind_param('ss',$name,$phone);$statement->execute();$statement=$connection->prepare('SELECT id FROM customers WHERE phone=?');$statement->bind_param('s',$phone);$statement->execute();$customer=$statement->get_result()->fetch_assoc();$statement=$connection->prepare('INSERT INTO installation_requests (customer_id,service_type,location,preferred_date,notes) VALUES (?,?,?,?,?)');$statement->bind_param('issss',$customer['id'],$service,$location,$date,$notes);$statement->execute();flash('success','Installation request received. Sammy Tech will confirm your appointment.');header('Location: ../installation.php');
